theorem ProbabilityTheory.extracted_1.{u_11, u_7, u_6, u_5} {Ω : Type u_5} {Ω' : Type u_6} {α : Type u_7}
  {T : Type u_11} {mΩ : MeasurableSpace Ω} {mΩ' : MeasurableSpace Ω'} [inst : MeasurableSpace α] {X : Ω → α}
  {Y : Ω' → α} {μ : T → Measure Ω} {μ' : T → Measure Ω'} {w : T → ℝ≥0∞} (hX : Measurable X) (hY : Measurable Y)
  (h_ident : ∀ (y : T), w y ≠ 0 → IdentDistrib X Y (μ y) (μ' y)) (y : T) (E : Set α) (a : MeasurableSet E)
  (hy : w y = 0) : (w y • (mapₗ X) (μ y)) E = (w y • (mapₗ Y) (μ' y)) E := by
  simp [hy]
